echo "Repair mise wrappers that the regenerate migration broke"

# A hand-edited wrapper that ran "$(mise which X)" where the bin name goes was
# regenerated by 1787573629 with the substitution escaped into a literal, so it
# now runs `\$\(mise\ which\ X\)` and fails. Put the substitution back, but only
# when the whole file is exactly what omarchy-mise-install writes for that
# line. Anything else is left alone.

bin_dir="$HOME/.local/bin"

[[ -d $bin_dir ]] || exit 0

for wrapper in "$bin_dir"/*; do
  [[ -f $wrapper && ! -L $wrapper && -r $wrapper ]] || continue
  (($(stat -c%s "$wrapper") <= 1024)) || continue

  contents=$(<"$wrapper")

  package=$(sed -n 's/^mise use -g --quiet "\(.*\)" || exit 1$/\1/p' <<<"$contents")
  tool=$(sed -n 's/^exec mise x ".*" -- \\\$\\(mise\\ which\\ \(.*\)\\) "\$@"$/\1/p' <<<"$contents")

  [[ -n $package && -n $tool ]] || continue
  [[ $package$tool != *[!A-Za-z0-9._+:/@-]* ]] || continue

  printf -v broken '#!/bin/bash\nexport MISE_MINIMUM_RELEASE_AGE=0\nmise use -g --quiet "%s" || exit 1\nexec mise x "%s" -- %q "$@"' \
    "$package" "$package" "\$(mise which $tool)"
  [[ $contents == "$broken" ]] || continue

  printf '#!/bin/bash\nexport MISE_MINIMUM_RELEASE_AGE=0\nmise use -g --quiet "%s" || exit 1\nexec mise x "%s" -- "$(mise which %s)" "$@"\n' \
    "$package" "$package" "$tool" >"$wrapper"
done
